if(settings.tariffSource!=='user'){settings.tariffSource='pudl';settings.tariff=statePrice()}
if(!Array.isArray(settings.weights)||settings.weights.length!==7||!settings.weights.every(Number.isFinite))settings.weights=[...defaultWeights];
const S={session:read('threshold-session',null),anc:true,phase:180,baseline:66.6,residual:54.2,freq:120,power:5.2,source:'demo',sampleTime:now(),baselineTime:now(),powerPeriod:'hour',energyWh:0,dbHours:0,events:[],outbox:[],spikeUntil:0,exceed:false,history:[],imported:null};
