function profileDialog(){dialog(`<h2>Configure threshold profile</h2><p>Illustrative values only. Profile names do not verify the applicable law.</p><form id="profile-form"><div class="field"><label for="profile-name">Profile</label><select id="profile-name"><option>Prince William County</option><option>Divide County</option><option>PennFuture model</option><option>Washtenaw County</option><option>Custom profile</option></select></div><div class="config-grid"><div class="field"><label for="day-limit">Day threshold (dBA)</label><input id="day-limit" type="number" min="20" max="120" required value="${settings.day}"></div><div class="field"><label for="night-limit">Night threshold (dBA)</label><input id="night-limit" type="number" min="20" max="120" required value="${settings.night}"></div></div><div class="field"><label for="timezone">Facility timezone</label><select id="timezone">${['America/New_York','America/Chicago','America/Denver','America/Los_Angeles','UTC'].map(z=>`<option ${z===settings.timezone?'selected':''}>${z}</option>`).join('')}</select></div><p class="footnote">Demo daytime is 07:00–22:00. A real ordinance may use different schedules, measurement periods, and locations.</p><div class="dialog-actions"><button type="button" class="btn outline" data-action="close">Cancel</button><button class="btn" type="submit">Save profile</button></div></form>`);$('#profile-name').value=settings.profile;$('#profile-name').addEventListener('change',e=>{const limits=PROFILE_LIMITS;if(limits[e.target.value]){$('#day-limit').value=limits[e.target.value][0];$('#night-limit').value=limits[e.target.value][1]}});$('#profile-form').addEventListener('submit',e=>{e.preventDefault();settings.profile=$('#profile-name').value;wxId=null;if(settings.tariffSource!=='user')settings.tariff=statePrice();settings.day=Number($('#day-limit').value);settings.night=Number($('#night-limit').value);settings.timezone=$('#timezone').value;persistSettings();closeDialog();costs();recordExceedance();toast('Illustrative threshold profile updated.')})}
