const sample={schema_version:1,device_id:'esp32-zone-01',sequence:1,timestamp:new Date().toISOString(),anc_enabled:true,baseline_level:66.6,residual_level:54.2,dominant_hz:120,cancellation_hz:120,phase_deg:180,power_w:5.2,voltage_v:5,current_a:1.04,measurement:{unit:'dB relative',calibrated:false,weighting:'Z',location:'duct',averaging:'RMS_1s'}};
function hardwareDialog(){dialog(`<h2>Hardware connection</h2><div class="hardware-state"><span class="badge amber">NOT CONNECTED</span><span>ESP32-S3 · INA219</span></div><p>The app is ready to display a documented telemetry payload. Your team's backend will authenticate devices, ingest readings, and acknowledge control commands.</p><div class="source-note">Hardware → authenticated backend → website.<br>Commands travel back through the backend. Time-critical ANC stays on the hardware.</div><label class="field-label" for="json-payload">Inspect a telemetry snapshot</label><textarea id="json-payload" class="code-input" spellcheck="false">${esc(JSON.stringify(sample,null,2))}</textarea><p id="json-error" class="form-error" role="alert"></p><div class="json-actions"><button class="btn small" data-action="import">Import snapshot</button><button class="btn outline small" data-action="restore-demo">Restore demo</button><button class="btn outline small" data-action="schema">Download sample JSON</button></div><p class="footnote">Snapshots are read-only, labeled imported, and never passed off as live. No secret keys belong in this page.</p><div class="dialog-actions"><button class="btn text" data-action="close">Close</button></div>`)}
function validatePayload(d){if(d.schema_version!==1)throw Error('schema_version must be 1.');for(const key of ['baseline_level','residual_level','dominant_hz','phase_deg','power_w'])if(typeof d[key]!=='number'||!Number.isFinite(d[key]))throw Error(`${key} must be a finite number.`);if(d.power_w<0||d.power_w>100000||d.dominant_hz<0||d.dominant_hz>20000||d.residual_level>180||d.residual_level< -160||d.baseline_level>180||d.baseline_level< -160)throw Error('Measurement outside supported bounds.');if(typeof d.anc_enabled!=='boolean')throw Error('anc_enabled must be true or false.');if(!d.device_id||Number.isNaN(Date.parse(d.timestamp)))throw Error('device_id and a valid timestamp are required.');if(!d.measurement||!['dBA','dB relative','dBFS'].includes(d.measurement.unit))throw Error('Provide measurement metadata with unit dBA, dB relative, or dBFS.');if(d.spectrum){const f=d.spectrum.frequency_hz,a=d.spectrum.baseline_db,b=d.spectrum.current_db;if(![f,a,b].every(Array.isArray)||f.length!==a.length||a.length!==b.length||f.length<2||f.length>2048||![...f,...a,...b].every(Number.isFinite))throw Error('Spectrum arrays must have matching lengths of 2–2048 finite numbers.')}return d}
function importSnapshot(){try{const d=validatePayload(JSON.parse($('#json-payload').value));S.imported=d;S.source='import';S.anc=d.anc_enabled;S.baseline=d.baseline_level;S.residual=d.residual_level;S.power=d.power_w;S.freq=d.dominant_hz;S.phase=d.phase_deg;S.sampleTime=d.timestamp;staleAt=Date.now();log('Telemetry snapshot imported',`${d.device_id}. Read-only snapshot, not a live stream.`);closeDialog();render();toast('Snapshot imported. Hardware controls are read-only.')}catch(e){$('#json-error').textContent=e.message}}
function download(name,text,type='text/plain'){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function exportReadings(){let rows=S.source==='demo'?S.history:[{timestamp:S.sampleTime,source:'imported-snapshot',anc:S.anc,baseline_level:S.baseline,residual_level:S.residual,unit:S.imported.measurement.unit,power_w:S.power}];if(!rows.length)return toast('Wait for the first demo sample.');const keys=Object.keys(rows[0]);download('threshold-readings.csv',[keys.join(','),...rows.map(r=>keys.map(k=>csvCell(r[k])).join(','))].join('\n'),'text/csv');toast('Readings exported with timestamps and source labels.')}
