function initReveals(){document.body.classList.add('js-reveal');const io=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}},{threshold:.08});$$('.reveal').forEach(el=>io.observe(el))}
function initHero(){
 const el=$('#hero'),stage=$('.hero-stage'),bands=$$('.hero-band'),video=$('.hero-video'),poster=$('.hero-image');
 const gates=['(max-width: 720px)','(orientation: portrait) and (max-width: 1024px)','(orientation: portrait) and (pointer: coarse)','(orientation: landscape) and (pointer: coarse) and (max-height: 560px)','(prefers-reduced-motion: reduce)'];
 const mq=gates.map(q=>matchMedia(q));let raf=null,shown=0,target=0,last=0,enabled=false,videoUrl=null,controller=null,seekBusy=false,pending=null,seekTimer=null,disposed=false,lastProgress=-1;
 const progress=()=>clamp((76-el.getBoundingClientRect().top)/(el.offsetHeight-stage.offsetHeight),0,1);
 const label=$('.scene-label');const setLabel=s=>{if(label&&label.dataset.label!==s){label.dataset.label=s;label.innerHTML='<strong>LANDSCAPE CONCEPT / 001</strong>'+s;}};
 function resetSeek(){seekBusy=false;pending=null;clearTimeout(seekTimer);}
 function seek(t){
  if(!Number.isFinite(t)||!Number.isFinite(video.duration)||video.duration<=0)return;
  t=clamp(t,0,Math.max(0,video.duration-.025));
  if(seekBusy){pending=t;return;}if(Math.abs(video.currentTime-t)<.02)return;
  seekBusy=true;try{video.currentTime=t;clearTimeout(seekTimer);seekTimer=setTimeout(()=>{seekBusy=false;pending=null;scroll();},1200);}catch{resetSeek();}
 }
 const seeked=()=>{seekBusy=false;clearTimeout(seekTimer);if(pending!==null){const t=pending;pending=null;seek(t);}};
 video.addEventListener('seeked',seeked);
 const failed=()=>{resetSeek();stage.classList.remove('video-ready');setLabel('Conceptual illustration.<br>Video unavailable. Try the watch button.');};
 video.addEventListener('error',failed);
 function update(p){
  const smooth=(x,a,b)=>{let t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t)};
  const op=[1-smooth(p,.29,.33),smooth(p,.33,.37)*(1-smooth(p,.64,.68)),smooth(p,.68,.72)];
  bands.forEach((b,i)=>{const k=op[i];if(Math.abs(Number(b.dataset.opacity??-1)-k)>.008){b.style.opacity=k;b.style.pointerEvents=k>.8?'auto':'none';b.classList.toggle('active',k>.8);b.dataset.opacity=k;}});
  const k=p<.33?0:p<.68?1:2;const counter=$('.hero-counter');const text='0'+(k+1)+' / 03';if(counter.textContent!==text)counter.textContent=text;
  const pct=Math.round(p*1000)/10;if(pct!==lastProgress){$('.hero-progress').style.width=pct+'%';lastProgress=pct;}
 }
 function tick(t){if(disposed||!enabled||document.hidden){raf=null;last=0;return;}const dt=Math.min(100,t-(last||t-16));last=t;shown+=(target-shown)*(1-Math.pow(.82,dt/16.667));if(Math.abs(target-shown)<.0005)shown=target;update(shown);seek(shown*video.duration);if(shown!==target)raf=requestAnimationFrame(tick);else{raf=null;last=0;}}
 function scroll(){if(!enabled||document.hidden||disposed)return;target=progress();if(raf===null)raf=requestAnimationFrame(tick);}
 async function loadFilm(){
  const film=window.THRESHOLD_HERO_VIDEO;if(!film||videoUrl||controller||disposed)return;
  const localCtrl=new AbortController();controller=localCtrl;let watchdog=setTimeout(()=>localCtrl.abort(),20000);
  try{
   setLabel('Loading the scroll film…');
   const res=await fetch(film,{signal:localCtrl.signal});if(!res.ok)throw Error('Video unavailable');
   const total=Number(res.headers.get('Content-Length'))||window.THRESHOLD_HERO_BYTES||0;
   const chunks=[];let got=0,lastPercent=-1;
   if(res.body?.getReader){const reader=res.body.getReader();while(true){const r=await reader.read();if(r.done)break;clearTimeout(watchdog);watchdog=setTimeout(()=>localCtrl.abort(),20000);chunks.push(r.value);got+=r.value.length;const percent=total?Math.min(100,Math.floor(got/total*100)):0;if(percent!==lastPercent){setLabel('Loading scroll film · '+percent+'%');lastPercent=percent;}}}
   else chunks.push(await res.arrayBuffer());
   if(disposed||!enabled)return;
   videoUrl=URL.createObjectURL(new Blob(chunks,{type:'video/mp4'}));video.src=videoUrl;video.load();
  }catch(e){if(!disposed&&enabled)failed();}finally{clearTimeout(watchdog);if(controller===localCtrl)controller=null;}
 }
 const ready=()=>{if(disposed)return;stage.classList.add('video-ready');setLabel('Scroll to bring the landscape to life.');scroll();};
 video.addEventListener('loadeddata',ready);
 function mode(){
  enabled=!mq.some(m=>m.matches);
  if(!enabled){if(raf!==null)cancelAnimationFrame(raf);raf=null;last=0;controller?.abort();resetSeek();bands.forEach((b,i)=>{b.classList.toggle('active',i===0);b.style.opacity=i===0?'1':'0';b.style.pointerEvents=i===0?'auto':'none';b.dataset.opacity=i===0?'1':'0';});poster.src=window.THRESHOLD_HERO_ENDING||'assets/hero-poster.jpg';setLabel('A quieter future, imagined.<br>Play the transformation with the watch button.');}
  else{poster.src=window.THRESHOLD_HERO_POSTER||'assets/hero-poster.jpg';scroll();loadFilm();}
 }
 const visibility=()=>{if(document.hidden){if(raf!==null)cancelAnimationFrame(raf);raf=null;last=0;}else scroll();};
 mq.forEach(m=>m.addEventListener('change',mode));addEventListener('scroll',scroll,{passive:true});addEventListener('resize',scroll);document.addEventListener('visibilitychange',visibility);mode();
 cleanupHero=()=>{disposed=true;removeEventListener('scroll',scroll);removeEventListener('resize',scroll);document.removeEventListener('visibilitychange',visibility);mq.forEach(m=>m.removeEventListener('change',mode));if(raf!==null)cancelAnimationFrame(raf);controller?.abort();resetSeek();video.removeEventListener('loadeddata',ready);video.removeAttribute('src');video.load();if(videoUrl)URL.revokeObjectURL(videoUrl);};
}
function watchFilm(){
 const src=window.THRESHOLD_HERO_VIDEO;if(!src)return toast('The landscape film is not configured.');
 dialog('<h2>A quieter future, imagined.</h2><p>A conceptual landscape transformation. This is not a measured ecological result.</p><video id="film-player" controls playsinline preload="metadata" style="width:100%;border-radius:7px" aria-label="Data center landscape transformation"></video><div class="dialog-actions"><button class="btn" data-action="close">Close</button></div>');
 const player=$('#film-player');player.src=src;player.play().catch(()=>{});
 $('#dialog').addEventListener('close',()=>{player.pause();player.removeAttribute('src');player.load();},{once:true});
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="watch-film"]'))watchFilm();});
